cd $TMPDIR/q && python3 -I -c "
import json,re
o=json.load(open('rows3.json'))
def b(c): return re.sub(r'\((?:[A-Za-z]{2,}(?:-[A-Za-z]+)*)\)','',c)
for r in o:
    if not any(b(c) in ('16(h)','20(a)(2)') for c in r['cites']): continue
    if r['head'] in (100,500,1000,2500,5500,6000,10000) or (r['rec'] and re.search(r'\.5000|^0\$|^0$', r['rec'])) or r['rec'] in (None,'') :
        print(r['file'],r['page'],r['cites'],r['head'],repr(r['rec'])[:200])
"
